'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(n,d=0)=>Number(n).toLocaleString('es-ES',{minimumFractionDigits:d,maximumFractionDigits:d});
const kg=n=>num(n)+' kg'; const ton=n=>num(n/1000,3)+' t';
const code=c=>c.replace(/(\d{2})(\d{2})(\d{2})/,'$1 $2 $3');
const ler=c=>LER.find(l=>l.code===c)||{name:c,family:'Otros',rule:'Pendiente de caracterización.',route:'Pendiente',hazard:false};
const color=f=>({'Minerales':'#6b99d8','Madera':'#b38e64','Vidrio':'#66b8b2','Plásticos':'#2775ef','Metales':'#8396ae','Yeso':'#8d9bcf','Envases':'#c2a16b','Peligrosos':'#d56d69','Mixtos':'#b2bbc6','Aislantes':'#82ada0','Tierras':'#947557'}[f]||'#93a3b5');
const icons={dashboard:'M3 3h7v7H3zM14 3h7v4h-7zM14 11h7v10h-7zM3 14h7v7H3z',layers:'m12 3 10 5-10 5L2 8zm-9 9 9 5 9-5M3 16l9 5 9-5',box:'m3 7 9-5 9 5v10l-9 5-9-5zm0 0 9 5 9-5M12 12v10m-4.5-17.5 9 5',activity:'M3 12h4l3-8 4 16 3-8h4',board:'M3 3h5v18H3zm7 0h5v11h-5zm7 0h4v16h-4z',truck:'M3 6h12v12H3zM15 10h4l3 4v4h-7M8 18a2 2 0 1 1-4 0m16 0a2 2 0 1 1-4 0',camera:'M4 6h4l2-3h4l2 3h4v15H4zM16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',team:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M13 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0M17 3a4 4 0 0 1 0 8m2 3a4 4 0 0 1 3 4v3',target:'M21 12a9 9 0 1 1-9-9m6 9a6 6 0 1 1-6-6m0 6 10-10m-6 0h6v6',book:'M3 3h6l3 3 3-3h6v17h-6l-3 2-3-2H3zm9 3v16',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6zm-5 9 4 4 6-6',chart:'M3 3v18h19M7 16v-4m5 4V8m5 8V4',scan:'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5M3 12h18',plus:'M12 4v16M4 12h16',arrow:'M4 12h16m-6-6 6 6-6 6',download:'M12 3v12m-5-5 5 5 5-5M3 16v5h18v-5',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 7v5l3 2',alert:'m12 3 10 18H2zm0 5v6m0 3v1',check:'m5 12 4 4L20 5',leaf:'M20 3C7 2 1 10 5 17s17 1 15-14zM5 20 15 9',bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5zm4 3h6',link:'m9 15 6-6m-5-3 2-2a5 5 0 0 1 7 7l-2 2m-3 5-2 2a5 5 0 0 1-7-7l2-2',file:'M5 2h9l5 5v15H5zm9 0v6h5M8 12h8m-8 4h8',search:'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0m-2 5 6 6'};
const ico=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.box}"/></svg>`;
const badge=s=>`<span class="badge ${({'Cerrado':'green','Listo':'blue','Acopio':'blue','Recibido':'amber','Revisión':'amber','Bloqueado':'red','Cuarentena':'red','Hecho':'green','Alta':'red','Media':'amber','Baja':'blue','Confirmada':'green','Solicitada':'amber'}[s]||'')}">${esc(s)}</span>`;
const cb=c=>`<span class="code ${c.endsWith('*')?'danger':''}">${code(c)}</span>`;
const seed={lots:seedLots,tasks:seedTasks,history:[{id:'E-0003',time:'2026-09-11T08:42:00+02:00',unit:'SAC-001',type:'Incidencia',actor:'Encargado · demo',note:'Humedad visible. Se solicita protección de la saca.',source:'Registro manual'},{id:'E-0002',time:'2026-09-11T08:18:00+02:00',unit:'SAC-002',type:'Lectura',actor:'WM · demo',note:'Unidad identificada en punto circular norte.',source:'QR · simulado'},{id:'E-0001',time:'2026-09-10T16:20:00+02:00',unit:'CNT-006',type:'Recepción',actor:'Gestor · demo',note:'760 kg recibidos; certificado final pendiente.',source:'Pesaje destino · demo'}],collections:[],messages:[{role:'Encargado',text:'Mañana empieza el corte de placas en planta 3. Necesitamos una saca de yeso protegida.',time:'09:15 · demo',unit:'SAC-001'},{role:'Waste manager',text:'Revisamos separación, etiquetado y acceso para retirada antes del inicio.',time:'09:20 · demo',unit:'SAC-001'}],learning:[],points:120,redemptions:[],target:90,minutes:[],photos:[],createdAt:'2026-09-11'};
let state;state=structuredClone(seed);
let route=location.hash.slice(1)||'control', filters={}, materialTab='catalogo', planTab='tablero', analysisTab='hallazgos', maskOn=true, scanStream=null, scanInterval=null;
let memoryOnly=false;
function persist(){}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4600)}
function log(unit,type,note,source='Registro manual',actor='Waste manager · demo'){state.history.unshift({id:'E-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),time:new Date().toISOString(),unit,type,note,source,actor});persist()}
const nav=[['OPERACIÓN','control','Centro de control','dashboard'],['','materiales','Materiales y LER','layers'],['','unidades','Sacas y contenedores','box'],['','registros','Registros e históricos','activity'],['','planificacion','Planificación','board'],['','gestores','Gestores y retiradas','truck'],['INTELIGENCIA Y EQUIPO','vision','Visión y control remoto','camera'],['','equipo','Equipo de obra','team'],['','objetivos','Objetivos y recompensas','target'],['','formacion','Formación','book'],['CRITERIO Y EVIDENCIA','normativa','Marco normativo','shield'],['','estudio','Análisis del proyecto','chart']];
function go(r){if(route===r){filters={};render()}else location.hash=r;$('#sidebar').classList.remove('open')}
function page(title,sub,act='',eyebrow='OPERACIONES / CUEVA'){return `<div class="pagehead"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions">${act}</div></div>`}
const btn=(txt,act,cls='',icon='')=>`<button class="${cls}" data-action="${act}">${icon?ico(icon):''}${txt}</button>`;
const metric=(label,value,meta,icon,cls='')=>`<div class="kpi ${cls}"><div class="label">${label}${ico(icon)}</div><div class="value">${value}</div><div class="meta">${meta}</div></div>`;
const familyOptions=()=>[...new Set(LER.map(l=>l.family))].map(f=>`<option>${f}</option>`).join('');
function demoNote(){return '<div class="notice">Los 13 lotes iniciales reproducen las masas del informe de 2025. Identificadores, estados, personas, fechas operativas, purezas, tarifas y justificantes son ejemplos de demostración.</div>'}
function totals(){const total=state.lots.reduce((s,l)=>s+l.kg,0),eligible=state.lots.filter(l=>l.code.startsWith('17')&&!ler(l.code).hazard&&l.code!=='170504'),base=eligible.reduce((s,l)=>s+l.kg,0),recycled=eligible.reduce((s,l)=>s+(l.status==='Cerrado'&&l.proof?l.recycled||0:0),0),closed=state.lots.filter(l=>l.status==='Cerrado').length, active=state.lots.filter(l=>!['Cerrado','Recibido'].includes(l.status));return{total,base,recycled,rate:base?100*recycled/base:0,closed,active,alerts:active.filter(l=>['Revisión','Bloqueado','Cuarentena'].includes(l.status))}}
function flowChart(){const t=totals(),inSite=t.active.reduce((s,l)=>s+l.kg,0),received=state.lots.filter(l=>l.status==='Recibido').reduce((s,l)=>s+l.kg,0),closed=state.lots.filter(l=>l.status==='Cerrado').reduce((s,l)=>s+l.kg,0);const groups=[['En obra',inSite,'#82aef7'],['Recibido · sin cierre',received,'#e4b961'],['Cerrado con evidencia',closed,'#43be94']];return `<svg viewBox="0 0 690 260" role="img" aria-label="Estado de la masa registrada: ${groups.map(g=>g[0]+' '+kg(g[1])).join(', ')}"><text x="12" y="27" font-size="12" fill="#798795">MASA REGISTRADA</text><text x="459" y="27" font-size="12" fill="#798795">ESTADO DEL EXPEDIENTE</text>${groups.map((g,i)=>`<path d="M193 ${90+i*31} C290 ${90+i*31} 314 ${75+i*74} 441 ${75+i*74}" fill="none" stroke="${g[2]}" stroke-opacity=".23" stroke-width="${Math.max(4,65*g[1]/t.total)}"/><rect x="439" y="${58+i*74}" width="5" height="36" rx="2" fill="${g[2]}"/><text x="457" y="${71+i*74}" fill="#445769" font-size="13">${g[0]}</text><text x="457" y="${92+i*74}" fill="#172c40" font-size="19" font-weight="600">${ton(g[1])}</text>`).join('')}<rect x="10" y="70" width="185" height="121" rx="10" fill="#101c2d"/><text x="29" y="100" fill="#9cafc3" font-size="12">${state.lots.length} LOTES IDENTIFICADOS</text><text x="29" y="143" fill="white" font-size="29" font-weight="600">${ton(t.total)}</text><text x="29" y="168" fill="#65e6b7" font-size="12">Cada kg tiene un origen</text><text x="12" y="249" fill="#8b98a6" font-size="11">Estados excluyentes · un cierre puede incluir rechazo y otras salidas.</text></svg>`}
function control(){const t=totals();return page('Control de circularidad','Viernes, 11 de septiembre de 2026 · entorno de trabajo de demostración',btn('Leer unidad','scan','','scan')+btn('Nuevo registro','new','primary','plus'),'OBRA / EL PRAT DE LLOBREGAT')+`<div class="kpis">${metric('Residuos registrados',`${num(t.total/1000,3)}<em>t</em>`,`${state.lots.length} lotes · todas las fracciones`,'layers')}${metric('Reciclado RCD acreditado',`${num(t.rate,1)}<em>%</em>`,`${kg(t.recycled)} / ${kg(t.base)} elegibles · demo`,'leaf','featured')}${metric('Unidades en obra',String(t.active.length),`${t.active.filter(l=>l.fill>=80).length} por encima del 80 % de llenado`,'box')}${metric('Requieren atención',String(t.alerts.length),'Calidad, aceptación o peligrosidad','alert')}</div><div class="grid2"><section class="panel"><div class="panelhead"><div><h2>Del acopio al siguiente ciclo</h2><small>Balance de masa · todos los registros de esta demo</small></div>${btn('Ver registros','nav:registros','ghost','arrow')}</div><div class="flow">${flowChart()}</div><div class="panelfoot between"><span>Cierre documental: ${t.closed} / ${state.lots.length} lotes</span><span class="badge green">Masa conciliada</span></div></section><section class="panel"><div class="panelhead"><h2>Una segunda mirada en obra</h2>${ico('camera')}</div><div class="photo"><img src="assets/piloto-contenedor.jpg" alt="Contenedor con residuos mezclados fotografiado durante el proyecto de RCD de 2025"><span class="label badge dark">Imagen de referencia</span><span class="right-label badge dark">Sin cámara en directo</span><span class="photocredit">Informe CREC 2025 · p. 83</span></div><div class="camera-body between"><div><h3>Mezcla visible → revisión humana</h3><p>Inspección y segmentación asistida.</p></div>${btn('Abrir','nav:vision','ghost','arrow')}</div></section></div><div class="grid2"><section class="panel"><div class="panelhead"><div><h2>Prioridades de hoy</h2><small>Lo que necesita una decisión del waste manager</small></div>${btn('Tablero','nav:planificacion','ghost','board')}</div><div class="tablewrap"><table><thead><tr><th>Unidad / fracción</th><th>Motivo</th><th>Responsable</th><th></th></tr></thead><tbody>${t.alerts.slice(0,4).map(l=>`<tr><td><strong>${l.id}</strong><small>${ler(l.code).name}</small></td><td>${badge(l.status)}</td><td>${l.status==='Cuarentena'?'Técnico RP':'Waste manager'}</td><td><button class="iconbtn" data-unit="${l.id}" aria-label="Abrir ${l.id}">${ico('arrow')}</button></td></tr>`).join('')||'<tr><td colspan="4">Sin incidencias pendientes.</td></tr>'}</tbody></table></div></section><section class="panel pad"><div class="between"><h2>Objetivo de obra</h2>${ico('target')}</div><div class="between spaced"><div class="big-number">${num(t.rate,1)}<span class="muted" style="font-size:1rem"> %</span></div><span class="badge blue">Meta ${state.target} %</span></div><div class="progress green"><span style="width:${Math.min(t.rate,100)}%"></span></div><p class="small muted">Reciclado acreditado sobre RCD no peligrosos elegibles. Envases y peligrosos se muestran por separado.</p><p class="small">Faltan ${kg(Math.max(0,t.base*state.target/100-t.recycled))} acreditados para la meta interna.</p>${btn('Desglose y fórmula','nav:objetivos','ghost','arrow')}</section></div>`+demoNote()}
function materials(){let all=LER.filter(l=>(!filters.q||fold(l.name+' '+l.code+' '+l.example+' '+l.rule).includes(fold(filters.q)))&&(!filters.family||l.family===filters.family));return page('Materiales y residuos','Identidad del producto, clasificación del residuo y condiciones de su siguiente uso.',btn('Asistente LER','classifier','','search')+btn('Exportar catálogo','export-ler','','download'),'REGISTRO / DICCIONARIO CUEVA')+`<div class="tabs"><button data-tab="material:catalogo" class="${materialTab==='catalogo'?'active':''}">Catálogo LER <span class="badge">${LER.length}</span></button><button data-tab="material:banco" class="${materialTab==='banco'?'active':''}">Banco de materiales</button><button data-tab="material:ciclo" class="${materialTab==='ciclo'?'active':''}">Circularidad CUEVA</button></div>`+(materialTab==='catalogo'?`<div class="toolbar"><input class="grow" id="filter-q" placeholder="Buscar: yeso, film, amianto, 170802…" aria-label="Buscar LER" value="${esc(filters.q||'')}"><select id="filter-family" aria-label="Familia"><option value="">Todas las familias</option>${familyOptions()}</select><span class="small muted">${all.length} entradas</span></div><div class="notice">LER identifica un <strong>residuo según origen y composición</strong>. Un producto en uso o un excedente reutilizable conserva su identidad de material. El asterisco indica residuo peligroso; la ausencia de una alerta visual no demuestra ausencia de peligrosidad.</div><section class="panel tablewrap"><table><thead><tr><th>Código LER</th><th>Fracción / uso operativo</th><th>Familia</th><th>Criterio de segregación</th><th></th></tr></thead><tbody>${all.map(l=>`<tr><td>${cb(l.code)}</td><td><strong>${l.name}</strong><small>${l.example}</small></td><td><span class="dot" style="background:${color(l.family)}"></span>${l.family}</td><td class="wrap">${esc(l.rule)}</td><td><button class="iconbtn" data-ler="${l.code}" aria-label="Ver ficha ${l.name}">${ico('arrow')}</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No hay resultados. Prueba otra fracción o código.</td></tr>'}</tbody></table></section><p class="small muted spaced">Selección operativa, no lista exhaustiva. Capítulos 08, 15, 16 y 17. <a href="${SOURCES.find(s=>s.id==='ler').url}" target="_blank" rel="noopener">Consultar denominaciones legales completas ↗</a></p>`:materialTab==='banco'?bank():cycle())}
function bank(){return `<div class="notice success">Antes de declarar un residuo, revisar devolución, mantenimiento y reutilización del producto. Los ejemplos siguientes son inventario de demostración y no se suman a los kg de residuos.</div><div class="grid3">${[['MAT-014','Panel de encofrado CUEVA','28 uds','15 mm · plástico reciclado','Inspección tras desencofrado','Mantenimiento'],['MAT-021','Palet retornable','16 uds','Madera · circuito de proveedor','Devolver al suministrador','Retorno'],['MAT-034','Placa de yeso completa','32 m²','Excedente protegido y sin instalar','Reservar para otra zona','Reutilización']].map(([id,name,qty,desc,next,status])=>`<div class="panel pad"><div class="between"><span class="code">${id}</span>${badge(status)}</div><h2 class="spaced">${name}</h2><p class="muted small">${desc}</p><div class="big-number" style="font-size:2.3rem">${qty}</div><div class="material-path"><span>Producto</span> → <span>${status}</span></div><p class="small muted">${next}</p>${btn('Ver pasaporte','passport:'+id,'ghost','arrow')}</div>`).join('')}</div><section class="panel pad"><h2>La condición jurídica también forma parte del pasaporte</h2><p class="muted">Producto reutilizable, residuo y material que ha dejado de ser residuo son estados distintos. Un cambio de estado exige fundamento y responsable. Un QR o un DPP no otorgan por sí solos el fin de condición de residuo.</p></section>`}
function cycle(){return `<section class="panel pad"><div class="eyebrow">PROPUESTA CUEVA / CIRCUITO A VALIDAR</div><h2>De un lote recuperado a un activo con vida propia</h2><div class="material-path"><span>Obra · origen</span> → <span>Lote de plástico</span> → <span>Tratamiento autorizado</span> → <span>Panel CUEVA</span></div><div class="grid3"><div><h3>01 / Recuperar</h3><p class="small muted">Sacas identificadas, composición caracterizada, impropios, humedad y aceptación de destino.</p></div><div><h3>02 / Transformar</h3><p class="small muted">Entrada pesada → proceso → rendimiento → nueva partida. Mantener los lotes padre y las pérdidas.</p></div><div><h3>03 / Volver a usar</h3><p class="small muted">Pasaporte sincronizado con fabricación, POI si se instala, mantenimiento, retorno y siguiente ciclo.</p></div></div><div class="notice">Plastic People: posible salida de transformación, sujeta a condiciones técnicas y contractuales. Calaf / CGM: entorno y operación. Inèdit: metodología ambiental. CUEVA: identidad, datos y continuidad entre agentes.</div><h3>El vínculo que no puede perderse</h3><p class="small muted">El identificador del contenedor persiste entre servicios. El del lote cambia con su contenido. La etiqueta referencia ambos; unir, dividir o transferir lotes conserva la genealogía y concilia masas.</p></section>`}
function units(){const ls=state.lots.filter(l=>(!filters.q||fold(l.id+' '+ler(l.code).name+' '+l.zone).includes(fold(filters.q)))&&(!filters.status||l.status===filters.status));return page('Sacas y contenedores','Localización, contenido y expediente de cada unidad física.',btn('Leer QR / identificador','scan','','scan')+btn('Añadir unidad','new','primary','plus'))+`<div class="toolbar"><input id="filter-q" class="grow" value="${esc(filters.q||'')}" aria-label="Buscar unidad" placeholder="Buscar por unidad, fracción o zona"><select id="filter-status" aria-label="Estado"><option value="">Todos los estados</option>${['Acopio','Listo','Revisión','Bloqueado','Cuarentena','Recibido','Cerrado'].map(s=>`<option>${s}</option>`).join('')}</select><span class="small muted">${ls.length} unidades</span></div><div class="unit-grid">${ls.map(l=>`<article class="unit" tabindex="0" role="button" data-unit="${esc(l.id)}" aria-label="Abrir ${esc(l.id)}"><div class="unit-top"><div class="unit-symbol" style="background:${color(ler(l.code).family)}15;color:${color(ler(l.code).family)}">${ico(l.id.startsWith('CNT')?'truck':'box')}</div>${badge(l.status)}</div><div class="between"><h3>${esc(l.id)}</h3>${cb(l.code)}</div><p class="small muted">${ler(l.code).name}</p><div class="between spaced"><b>${kg(l.kg)}</b><span class="small muted">${l.fill}% de llenado</span></div><div class="progress ${l.fill>80?'amber':'green'}"><span style="width:${l.fill}%"></span></div><div class="unit-bottom"><span>${esc(l.zone)}</span><span>${l.date.slice(8)}/${l.date.slice(5,7)}</span></div></article>`).join('')||'<div class="empty">No hay unidades con estos filtros.</div>'}</div>`}
function records(){const events=state.history.filter(e=>!filters.q||fold(Object.values(e).join(' ')).includes(fold(filters.q)));return page('Registros e históricos','Cada cambio conserva autor, momento, método y unidad vinculada.',btn('Exportar CSV','export-records','','download')+btn('Nuevo registro','new','primary','plus'))+`<div class="grid3">${metric('Eventos registrados',String(state.history.length),'Correcciones mediante nuevos eventos','activity')}${metric('Lotes con cierre',String(totals().closed),'Tratamiento y referencia de evidencia · demo','file')}${metric('Datos y fotos',String(state.photos.length),'Evidencias añadidas en este navegador','camera')}</div><div class="toolbar"><input id="filter-q" class="grow" placeholder="Buscar unidad, autor o evento" value="${esc(filters.q||'')}" aria-label="Buscar en histórico">${btn('Copia completa JSON','export-json','','download')}</div><div class="panel tablewrap"><table><thead><tr><th>Fecha / hora</th><th>Unidad</th><th>Evento</th><th>Autor / método</th><th>Detalle</th></tr></thead><tbody>${events.map(e=>`<tr><td>${new Date(e.time).toLocaleDateString('es-ES')}<small>${new Date(e.time).toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Madrid'})} · Europe/Madrid</small></td><td><button class="ghost" data-unit="${esc(e.unit)}">${esc(e.unit)}</button></td><td>${badge(e.type)}</td><td>${esc(e.actor)}<small>${esc(e.source)}</small></td><td class="wrap">${esc(e.note)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Sin eventos para esta búsqueda.</td></tr>'}</tbody></table></div><div class="notice spaced">El histórico local demuestra el flujo. La versión operativa requerirá autenticación, permisos, registro de auditoría en servidor y conservación documental. El CSV no es una presentación oficial ante eSIR o SDR.</div>`}
function planning(){return page('Planificación y coordinación','Del aviso de obra a la tarea resuelta, con responsables y fechas.',btn('Mapa de relaciones','nav:mapa','','link')+btn('Nueva tarea','newtask','primary','plus'))+`<div class="tabs"><button data-tab="plan:tablero" class="${planTab==='tablero'?'active':''}">Tablero</button><button data-tab="plan:agenda" class="${planTab==='agenda'?'active':''}">Agenda</button><button data-tab="plan:tiempos" class="${planTab==='tiempos'?'active':''}">Tiempos del WM</button></div>`+(planTab==='tablero'?`<div class="board">${['Por hacer','En curso','Bloqueado','Hecho'].map(s=>`<section class="column" data-drop="${s}"><div class="column-head"><span><span class="dot" style="background:${s==='Hecho'?'#2bb48b':s==='Bloqueado'?'#db7d69':'#8296b0'}"></span>${s}</span><span>${state.tasks.filter(t=>t.stage===s).length}</span></div>${state.tasks.filter(t=>t.stage===s).map(t=>`<article class="task" draggable="true" data-task="${t.id}"><div class="between"><span class="stamp">${esc(t.id)}</span>${badge(t.priority)}</div><h3>${esc(t.title)}</h3><div class="row small muted">${ico('box')}${esc(t.unit)}</div><div class="between" style="margin-top:15px"><span class="due ${t.due<'2026-09-11'&&s!=='Hecho'?'late':''}">${t.due.slice(8)}/${t.due.slice(5,7)}</span><span class="badge">${esc(t.owner)}</span></div><select aria-label="Estado de ${esc(t.title)}" data-task-stage="${t.id}">${['Por hacer','En curso','Bloqueado','Hecho'].map(v=>`<option ${v===s?'selected':''}>${v}</option>`).join('')}</select></article>`).join('')}</section>`).join('')}</div><p class="board-foot">Arrastra las tarjetas o cambia su estado con el selector. Los cambios se guardan en el espacio privado y se incorporan al histórico.</p>`:planTab==='agenda'?`<section class="panel calendar-list">${[...state.tasks].sort((a,b)=>a.due.localeCompare(b.due)).map(t=>`<div class="day"><div class="date">${t.due.slice(8)}<small>SEP 2026</small></div><div><h3>${esc(t.title)}</h3><span class="small muted">${esc(t.owner)} · ${esc(t.unit)}</span> ${badge(t.stage)}</div><button data-action="edit-task:${t.id}">Ver tarea</button></div>`).join('')}</section>`:timeView())}
function timeView(){const minutes=state.minutes.reduce((s,m)=>s+m.minutes,0);return `<div class="grid-even"><section class="panel pad"><h2>Dedicación real por actividad</h2><p class="small muted">El piloto plantea un WM multiobra. Antes de dimensionarlo, hay que conocer su carga y la de los operarios de cada obra.</p><div class="statrow"><div><b>${num(minutes/60,1)} h</b><small>Registradas en demo</small></div><div><b>${state.minutes.length}</b><small>Partes</small></div><div><b>1</b><small>Obra de ejemplo</small></div></div><form id="time-form"><div class="detailgrid"><div class="field"><label>Actividad</label><select name="activity"><option>Inspección y segregación</option><option>Logística y retirada</option><option>Formación</option><option>Documentación</option><option>Desplazamiento</option><option>Revisión remota</option></select></div><div class="field"><label>Minutos</label><input name="minutes" type="number" min="1" max="1440" required value="30"></div></div><button class="primary">Registrar tiempo</button></form></section><section class="panel pad"><h2>Cómo decidir la capacidad multiobra</h2><ul class="plain-list"><li>Carga presencial por fase, número de fracciones y generación diaria.</li><li>Desplazamientos, ventanas de retirada y distancia al gestor.</li><li>Horas de operarios locales: la separación física sigue siendo necesaria.</li><li>Tiempo documental y respuesta a excepciones.</li><li>Ocupación del acopio y plazo de reacción acordado.</li></ul><div class="notice">Capacidad = horas disponibles / horas demandadas por obra. Es una hipótesis a medir; las cámaras no eliminan el trabajo de campo.</div></section></div><section class="panel tablewrap"><table><thead><tr><th>Actividad</th><th>Fecha</th><th>Minutos</th></tr></thead><tbody>${state.minutes.map(m=>`<tr><td>${esc(m.activity)}</td><td>${new Date(m.date).toLocaleDateString('es-ES')}</td><td>${m.minutes}</td></tr>`).join('')||'<tr><td colspan="3">Todavía no hay partes. Registra la primera actividad.</td></tr>'}</tbody></table></section>`}
function managersView(){return page('Gestores y retiradas','Elegir el destino por fracción, calidad, autorización y capacidad de recepción.',btn('Solicitar retirada','collection','primary','truck'))+`<div class="notice warn">Directorio demostrativo. No se han verificado NIMA, autorizaciones, centros, operaciones ni tarifas de las empresas. Ninguna solicitud de este prototipo se envía fuera del navegador.</div><div class="toolbar"><select id="manager-code" aria-label="Filtrar gestores por LER"><option value="">Todas las fracciones</option>${[...new Set(state.lots.map(l=>l.code))].map(c=>`<option value="${c}">${code(c)} · ${ler(c).name}</option>`).join('')}</select><span class="small muted">Compatibilidad orientativa · aceptación por confirmar</span></div><div class="grid3">${managers.filter(m=>!filters.managerCode||m.codes.includes(filters.managerCode)).map(m=>`<section class="panel pad manager" style="border-top-color:${m.color}"><div class="between"><div class="initials" style="color:${m.color}">${m.name.slice(0,2).toUpperCase()}</div><span class="badge amber">Sin verificar</span></div><h2 class="spaced">${m.name}</h2><p class="small muted">${m.type}</p><div class="codes">${m.codes.map(cb).join('')}</div><div class="between small"><span>Plazo ilustrativo</span><b>${m.eta}</b></div><div class="between small" style="margin-top:10px"><span>Tarifa ilustrativa</span><b>${num(m.price)} €/t</b></div><div class="progress" style="background:#f0f3f6;margin:17px 0 14px"></div>${btn('Ver condiciones','manager:'+m.name,'ghost','arrow')}</section>`).join('')||'<div class="panel empty">No hay destino para esta fracción. El lote debe permanecer pendiente de aceptación.</div>'}</div><section class="panel"><div class="panelhead"><h2>Retiradas solicitadas</h2><span class="badge">${state.collections.length}</span></div><div class="tablewrap"><table><thead><tr><th>Solicitud</th><th>Unidad</th><th>Destino</th><th>Ventana</th><th>Estado</th><th></th></tr></thead><tbody>${state.collections.map(c=>`<tr><td>${esc(c.id)}</td><td>${esc(c.unit)}</td><td>${esc(c.manager)}</td><td>${esc(c.date)}<small>${esc(c.time)}</small></td><td>${badge(c.status)}</td><td>${btn('Expediente','unit:'+c.unit,'ghost','arrow')}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No hay solicitudes. Selecciona una unidad y prepara la primera retirada.</td></tr>'}</tbody></table></div></section>`}
function vision(){return page('Visión y control remoto','Detectar indicios, revisar evidencias y resolver incidencias desde cualquier lugar.',btn('Conexiones y cámaras','connections','','link')+btn('Añadir fotografía','photo','primary','camera'),'INTELIGENCIA / REVISIÓN ASISTIDA')+`<div class="grid2"><section class="panel"><div class="panelhead"><div><h2>Punto de acopio · imagen de referencia</h2><small>Fotografía del informe 2025 · no es una emisión en directo</small></div><label class="row small"><input type="checkbox" id="mask-toggle" ${maskOn?'checked':''}> Máscaras demo</label></div><figure class="vision-frame"><img src="assets/piloto-contenedor.jpg" alt="Fotografía de un contenedor con mezcla de residuos, usada para demostrar la revisión de imágenes"><svg viewBox="0 0 1919 649" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Regiones ilustrativas predefinidas, sin clasificación real" style="display:${maskOn?'block':'none'}"><polygon class="mask" points="553,180 918,210 1190,362 994,467 574,362" fill="#52d1f4" stroke="#52d1f4"/><polygon class="mask" points="1070,35 1250,48 1300,141 1040,175" fill="#efcb6b" stroke="#efcb6b"/><polygon class="mask" points="1260,91 1450,126 1490,220 1213,227" fill="#7ceba7" stroke="#7ceba7"/></svg><div class="caption"><span class="badge dark">MUESTRA ESTÁTICA</span></div><div class="vision-bottom"><span class="badge dark">Revisión pendiente · LER sin asignación automática</span></div></figure><div class="panelfoot">Las regiones son ilustrativas y predefinidas. No se ha ejecutado un modelo de segmentación sobre esta imagen.</div><div class="pad"><div class="between"><h3>Qué se puede revisar</h3><span class="badge amber">Validación humana</span></div><div class="seg-result"><i class="mark" style="background:#4dc8e8"></i><div><b>Indicios de mezcla e impropios</b><p>Detectar materiales visibles, ocupación y cambio entre capturas.</p></div></div><div class="seg-result"><i class="mark" style="background:#e5be59"></i><div><b>Lo que la imagen no acredita</b><p>Masa, polímero, contaminantes, amianto, peligrosidad ni reciclado efectivo.</p></div></div>${btn('Registrar revisión visual','visual-review','primary','check')}</div></section><div><section class="panel pad"><div class="between"><h2>Cola de inspección</h2>${badge('3 pendientes')}</div>${state.lots.filter(l=>['Revisión','Bloqueado','Cuarentena'].includes(l.status)).slice(0,3).map(l=>`<div class="chatline"><div class="between"><b class="small">${l.id} · ${ler(l.code).name}</b>${badge(l.status)}</div><p class="small muted">${esc(l.note)}</p>${btn('Abrir expediente','unit:'+l.id,'ghost','arrow')}</div>`).join('')}</section><section class="panel pad spaced"><h2>Del sensor a una decisión</h2><ul class="plain-list"><li>Captura con cámara o móvil vinculada a la unidad.</li><li>Control de calidad: oscuridad, polvo, oclusión y encuadre.</li><li>Detección y segmentación por modelo versionado.</li><li>Confianza calibrada y clase «desconocido».</li><li>Validación del WM y tarea de corrección.</li></ul><span class="badge blue">Diseño del servicio IA · pendiente de implementación</span></section></div></div><section class="panel pad"><div class="between"><h2>Evidencias fotográficas añadidas</h2><span class="badge">${state.photos.length}</span></div>${state.photos.length?`<div class="grid3 spaced">${state.photos.map(p=>`<div><img class="photo-evidence" src="${esc(p.data)}" alt="${esc(p.note||'Evidencia de '+p.unit)}"><b class="small">${esc(p.unit)}</b><p class="small muted">${esc(p.note)}</p><span class="badge">Revisión manual · sin inferencia IA</span></div>`).join('')}</div>`:'<p class="small muted spaced">Añade una imagen de una saca o contenedor y registra una observación.</p>'}</section>`}
function team(){return page('Equipo de obra','Cada aviso vinculado a una unidad; cada acción con un responsable.',btn('Nuevo aviso','message','primary','plus'),'EQUIPO / COORDINACIÓN')+`<div class="grid3">${[['WM','Waste manager','Control operativo',['Planifica la segregación y valida incidencias.','Propone LER y solicita revisión técnica.','Coordina destinos, retirada y expediente.']],['EO','Encargado de obra','Ejecución diaria',['Anticipa fases y nuevos materiales.','Organiza operarios y zonas de acopio.','Confirma correcciones en campo.']],['GT','Gestor / técnico','Aceptación y tratamiento',['Verifica aceptación y habilitaciones.','Registra recepción, rechazos y pesajes.','Aporta evidencia de tratamiento final.']]].map(([inits,title,sub,items])=>`<section class="panel role-card"><div class="avatar">${inits}</div><h2>${title}</h2><p class="small muted">${sub}</p><ul>${items.map(x=>`<li>${x}</li>`).join('')}</ul><span class="badge">Perfil demostrativo</span></section>`).join('')}</div><div class="grid-even"><section class="panel pad"><div class="between"><h2>Conversación de obra</h2><span class="badge">Local · sin envío</span></div>${state.messages.map(m=>`<article class="chatline"><div class="between"><b class="small">${esc(m.role)}</b><small>${esc(m.time)}</small></div><p>${esc(m.text)}</p><span class="code">${esc(m.unit)}</span></article>`).join('')}<form id="message-form"><div class="detailgrid"><div class="field"><label>Responsable</label><select name="role"><option>Waste manager</option><option>Encargado</option><option>Operario</option><option>Gestor</option></select></div><div class="field"><label>Unidad</label><select name="unit">${state.lots.map(l=>`<option>${l.id}</option>`).join('')}</select></div><div class="field full"><label>Mensaje</label><textarea name="message" required maxlength="800" placeholder="Indica qué ocurre y qué acción se necesita…"></textarea></div></div><button class="primary">Registrar aviso</button></form></section><section class="panel pad"><h2>Responsabilidades y permisos propuestos</h2><p class="small muted">Promotor / productor, constructor / poseedor, transportista, operador del traslado y gestor conservan sus responsabilidades. El WM es una función organizativa, no una licencia de tratamiento.</p><div class="checkline">${ico('check')} Operario: identificar, fotografiar y avisar.</div><div class="checkline">${ico('check')} Encargado: asignar medios y confirmar correcciones.</div><div class="checkline">${ico('check')} WM: preparar expedientes y coordinar retiradas.</div><div class="checkline">${ico('check')} Gestor: aceptar o rechazar y documentar el proceso.</div><div class="checkline">${ico('check')} Auditor: consulta de evidencias y trazabilidad.</div><div class="notice spaced">En este prototipo no hay cuentas ni permisos multiusuario. La versión operativa debe aplicar autorización en servidor por empresa, obra y función.</div></section></div>`}
function goals(){const t=totals(),gap=Math.max(0,t.base*state.target/100-t.recycled);return page('Objetivos y recompensas','Premiar la calidad, la prevención y la evidencia verificable.',btn('Editar meta','target','','target'),'MEJORA / RESULTADOS')+`<div class="grid3"><section class="panel goal"><div class="between"><h2>Reciclado material</h2>${ico('leaf')}</div><div class="metric">${num(t.rate,1)} % <small>/ ${state.target} %</small></div><div class="progress green"><span style="width:${Math.min(t.rate,100)}%"></span></div><p class="small muted">Meta interna. Numerador: ${kg(t.recycled)} acreditados. Denominador: ${kg(t.base)} de RCD no peligrosos, sin 17 05 04.</p><span class="badge amber">Faltan ${kg(gap)}</span></section><section class="panel goal"><h2>Expedientes completos</h2><div class="metric">${t.closed} <small>/ ${state.lots.length} lotes</small></div><div class="progress"><span style="width:${100*t.closed/state.lots.length}%"></span></div><p class="small muted">Cierre exige recepción, operación final, cantidad acreditada y referencia documental.</p></section><section class="panel goal"><h2>Formación de base</h2><div class="metric">${state.learning.length} <small>/ 3 módulos</small></div><div class="progress"><span style="width:${100*state.learning.length/3}%"></span></div><p class="small muted">Avance de esta sesión. Completar contenido no equivale a acreditar una titulación.</p>${btn('Continuar formación','nav:formacion','ghost','arrow')}</section></div><div class="grid-even"><section class="panel pad reward"><div class="eyebrow" style="color:#90b6cf">RECONOCIMIENTO DEL EQUIPO</div><h2>Circular points</h2><div class="big-number spaced" style="color:white">${state.points} <span style="font-size:1rem;color:#a6bcd2">pts</span></div><p class="spaced">Saldo ilustrativo inicial de 120 puntos. Cada módulo aporta 20 una sola vez. Una recompensa de reconocimiento consume 100 puntos.</p>${btn('Canjear reconocimiento · 100 pts','redeem','mint','target')}<p class="small" style="margin-top:14px">Canje simbólico y local · sin dinero ni premio externo.</p></section><section class="panel pad"><h2>Reglas para un incentivo sano</h2><ul class="plain-list"><li>Reconocer prevención, calidad y mejoras confirmadas.</li><li>No premiar solo toneladas: podría incentivar generar más residuos.</li><li>No restar puntos por comunicar incidentes de seguridad.</li><li>Evitar clasificaciones públicas de personas y decisiones automáticas laborales.</li><li>Validar resultados de equipo antes de un incentivo económico.</li></ul><p class="small muted">Reconocimientos canjeados: ${state.redemptions.length}.</p></section></div><section class="panel pad"><h2>Cómo leer el indicador</h2><p class="small muted">Esta tasa de demostración mide reciclado material acreditado. El objetivo estatal del 70 % incorpora además otras valorizaciones materiales y relleno en su ámbito; R1 (energía), R12 y R13 no se computan aquí como reciclado final. El 90 % es una meta interna de esta demo y no declara alineamiento con Taxonomía.</p>${btn('Ver reglas y fuentes','nav:normativa','ghost','arrow')}</section>`}
const lessons=[{id:'segregacion',title:'Separar en el punto de generación',mins:6,body:'Reserva un recipiente por flujo y comprueba la señalética antes de empezar. El yeso debe permanecer seco y sin mezcla con minerales. El film de embalaje pertenece al circuito de envases; un recorte de tubería pertenece al circuito del material constructivo. Si aparece un material desconocido, detén la clasificación y pide revisión.',question:'Caso de trabajo: ¿dónde registramos un film de embalaje limpio?',answers:['Envase plástico · 15 01 02','Plástico constructivo · 17 02 03','Mixto · 17 09 04'],correct:0},{id:'peligrosos',title:'Identificar dudas y peligrosidad',mins:8,body:'El asterisco del LER señala un residuo peligroso. La etiqueta del producto, su ficha de datos de seguridad y la caracterización del residuo aportan información, pero el nombre comercial o una foto no bastan. Aísla incidencias y solicita al responsable técnico la evaluación. Material sospechoso de amianto requiere circuito especializado.',question:'Caso de trabajo: una cámara no detecta peligrosidad. ¿Qué significa?',answers:['Que el residuo es no peligroso','Que la imagen no permite descartar peligrosidad','Que puede mezclarse con escombro'],correct:1},{id:'trazabilidad',title:'Cerrar el ciclo con evidencia',mins:7,body:'Leer una etiqueta acredita una observación del identificador, no el contenido ni el tratamiento. Mantén peso estimado y pesaje real separados. Conserva la unidad física, el lote y los documentos del traslado. R13 y R12 son etapas intermedias; el cierre circular exige conocer el tratamiento final y su cantidad acreditada.',question:'Caso de trabajo: el gestor ha recibido una saca en R13. ¿Está acreditado su reciclado?',answers:['Sí, al salir de obra','Sí, si hay QR','No, falta el tratamiento final'],correct:2}];
function learning(){return page('Formación en el momento de actuar','Guías breves para operarios, encargados y waste managers.',btn('Ver objetivos','nav:objetivos','','target'),'ACADEMIA / CUEVA')+`<div class="grid3">${lessons.map((l,i)=>`<article class="panel lesson"><div class="between"><span class="lesson-num">0${i+1}</span>${state.learning.includes(l.id)?badge('Hecho'):'<span class="badge">Pendiente</span>'}</div><span class="duration">${l.mins} min · guía y caso de trabajo</span><h2 style="margin-top:12px">${l.title}</h2><div class="progress green"><span style="width:${state.learning.includes(l.id)?100:0}%"></span></div>${btn(state.learning.includes(l.id)?'Repasar módulo':'Abrir módulo','lesson:'+l.id,'primary','book')}</article>`).join('')}</div><div class="notice">Contenido introductorio orientado a este prototipo. Los procedimientos de cada obra y la formación especializada en residuos peligrosos deben ser definidos por los responsables competentes.</div><section class="panel pad"><h2>Aprender desde la incidencia</h2><div class="grid3 spaced"><div><span class="badge amber">Yeso húmedo</span><p class="small muted spaced">Abrir la guía de protección y segregación al registrar una incidencia de humedad.</p></div><div><span class="badge red">Material desconocido</span><p class="small muted spaced">Pedir identificación técnica y activar una tarea de revisión.</p></div><div><span class="badge blue">Retirada pendiente</span><p class="small muted spaced">Comprobar etiqueta, documentación y condiciones del destino antes de cargar.</p></div></div></section>`}
const rules=[
['Responsabilidades','El WM coordina. Productor, poseedor, operador del traslado, transportista y gestor conservan sus obligaciones. Verificar quién actúa en cada función.','RD 105/2008','rd'],
['Planificación','Vincular estudio de gestión, plan de obra, separación prevista y destinos documentados. La operativa debe partir de la fase constructiva.','Estudio + plan','rd'],
['Clasificación','Desde 01/07/2022: madera, minerales, metales, vidrio, plástico y yeso; clasificación preferente en origen. Demolición selectiva obligatoria desde 01/01/2024.','Ley 7/2022 · art. 30','ley'],
['Almacenamiento','En producción: no peligrosos, menos de 2 años para valorización y de 1 para eliminación; peligrosos, máximo 6 meses salvo ampliación autorizada. Registrar inicio.','Art. 21','ley'],
['Traslado','Preparar contrato de tratamiento y DI. Evaluar notificación previa según residuo, operación y ámbito; no asumir que todos los RCD la necesitan.','RD 553/2020','traslado'],
['Recepción','Separar salida, llegada, aceptación/rechazo y tratamiento. En el régimen del RD 553/2020, el DI completo debe devolverse en el plazo máximo de 30 días desde entrega.','Control documental','traslado'],
['Archivo','Archivo electrónico para sujetos obligados; conservar información al menos 5 años. El registro CUEVA debe poder reconciliar documentos y masas.','Art. 64','ley'],
['Cataluña','Documento de aceptación y depósito ante gestor: 11 €/t prevista, mínimo 150 €, con las exclusiones aplicables. No confundir con una tarifa de tratamiento.','Decret 89/2010 modificado','cat'],
['Taxonomía','Definir actividad, objetivo y versión. El 90 % de ciertos criterios de contribución circular no equivale al objetivo estatal del 70 %. No existe un 50 %/15 % universal.','Criterio por actividad','tax'],
['Producto / residuo','El pasaporte conserva datos. No concede fin de condición de residuo, certificación de producto ni cumplimiento automático del CPR.','Reglamento 2024/3110','cpr'],
['Tierras','APM/1007/2017 regula valorización de materiales naturales excavados en otras obras; no los declara automáticamente subproductos.','Régimen específico','tierras'],
['Cámaras','Definir finalidad y necesidad, minimizar personas identificables, informar, restringir accesos y fijar conservación. La revisión de residuos no justifica vigilancia laboral indiscriminada.','Protección de datos','aepd']
];
function legal(){return page('Marco normativo','Reglas operativas con fuente, ámbito y evidencia necesaria. Revisión: 11/09/2026.',btn('Fuentes del análisis','sources','','file'),'CUMPLIMIENTO / REGLAS DE DECISIÓN')+`<div class="notice">Ámbito base: España + Cataluña, por la ubicación del piloto. Para llevarlo a Baleares hay que configurar su normativa, procedimientos e instalaciones; no trasladar automáticamente los requisitos catalanes.</div><section class="panel">${rules.map(([title,desc,label,id])=>`<div class="rule"><div><h3>${title}</h3><a class="small" href="${SOURCES.find(s=>s.id===id).url}" target="_blank" rel="noopener">Fuente oficial ↗</a></div><div><p>${desc}</p></div><span class="badge">${label}</span></div>`).join('')}</section><div class="grid-even spaced"><section class="panel pad"><h2>Documentos por expediente</h2><div class="taglist">${['Estudio de gestión','Plan de obra','Caracterización','Contrato de tratamiento','Aceptación de destino','DI','Notificación si procede','Pesaje','Rechazo / incidencias','Tratamiento final'].map(t=>`<span class="badge">${t}</span>`).join('')}</div><p class="small muted">Registrar emisor, referencia, fecha, vigencia, versión y lote. Un nombre de archivo no prueba autenticidad; la implantación necesitará revisión documental y controles de acceso.</p></section><section class="panel pad"><h2>Semáforo de producto propuesto</h2><div class="checkline"><span class="badge green">Verificado</span><span>Evidencia revisada y ámbito correcto.</span></div><div class="checkline"><span class="badge amber">Pendiente</span><span>Dato o documento sin resolver.</span></div><div class="checkline"><span class="badge red">Bloqueado</span><span>No avanzar hasta revisión.</span></div><p class="small muted">El prototipo ilustra estas decisiones; no emite certificados ni sustituye plataformas administrativas.</p></section></div>`}
function bars(values,labels,unit='kgCO₂e'){const max=Math.max(...values);return `<div class="bar-chart">${values.map((v,i)=>`<div class="bar-row"><span>${labels[i]}</span><div class="bar-track"><i style="width:${100*v/max}%;background:${['#a5b1c2','#4e8de5','#2caf89'][i]}"></i></div><b>${num(v,1)}<small class="muted"> ${unit}</small></b></div>`).join('')}</div>`}
function study(){return page('Del piloto a CUEVA Waste Manager','Lectura crítica del proyecto compartido por Mariano / CGM. Informe CREC, agosto de 2025.',btn('Fuentes','sources','','file')+`<a class="download-report" href="CUEVA_Waste_Manager_Analisis.pdf" download>Descargar análisis PDF ↗</a>`,'ANÁLISIS / FUNDAMENTOS DEL PROTOTIPO')+`<div class="kpis">${metric('Obra residencial','101<em>viviendas</em>','El Prat · 8.039 m² + 3.255 m² bajo rasante','box')}${metric('Piloto','5,955<em>t</em>','07/07–07/08/2025 · 13 flujos','layers')}${metric('Escala de obra','586,845<em>t</em>','Extrapolación económica · no nuevo ensayo','chart')}${metric('Idea que escalamos','WM','Persona + método + datos + destinos','team','featured')}</div><div class="tabs"><button data-tab="analysis:hallazgos" class="${analysisTab==='hallazgos'?'active':''}">Hallazgos y correcciones</button><button data-tab="analysis:graficos" class="${analysisTab==='graficos'?'active':''}">Gráficos y cifras</button><button data-tab="analysis:modelo" class="${analysisTab==='modelo'?'active':''}">Propuesta operativa</button></div>`+(analysisTab==='hallazgos'?`<div class="notice success"><strong>Mi conclusión:</strong> el valor está en profesionalizar la operación y asegurar salidas reales para materiales homogéneos. CUEVA puede convertirlo en un sistema compartido, con identidad del lote, coordinación multiagente y prueba de destino. Las cifras del estudio necesitan reconciliación antes de usarlas como compromiso comercial.</div><section class="panel audit">${AUDIT.map((a,i)=>`<details ${i<2?'open':''}><summary><span class="badge ${a[3]==='Corregir'?'red':a[3]==='Diseño'?'green':'amber'}">${a[3]}</span>${a[0]}</summary><small>Informe · ${a[1]}</small><p>${a[2]}</p></details>`).join('')}</section>`:analysisTab==='graficos'?charts():modelView())}
function charts(){return `<div class="grid-even"><section class="panel pad"><div class="between"><h2>Piloto · emisiones de gestión</h2><span class="badge">5,955 t</span></div>${bars([3371.98,1039,369.6],['Desfavorable','Actual · triaje','WM en obra'])}<div class="between"><span class="badge green">−64,4 % vs. actual</span><span class="badge">−89,0 % vs. desfavorable</span></div><p class="small muted spaced">Totales publicados, pp. 85–87. Factores de transporte y tratamiento; no medición directa de emisiones. La tabla económica usa 369,8: diferencia pendiente de reconciliar.</p></section><section class="panel pad"><div class="between"><h2>Obra completa · simulación</h2><span class="badge">≈586,85 t</span></div>${bars([195615.6,72774.8,32762.8],['Desfavorable','Actual · triaje','WM en obra'])}<div class="between"><span class="badge green">−55,0 % vs. actual</span><span class="badge">−83,3 % vs. desfavorable</span></div><p class="small muted spaced">Totales publicados, pp. 102–105. El 83 % del resumen se refiere a esta comparación; no a una reducción medida de toda la obra ni del edificio.</p></section></div><div class="grid-even"><section class="panel pad"><h2>Coste de la constructora · simulación</h2>${bars([111040.1,24409.2,39058.4],['Desfavorable','Actual','Con WM'],'€')}<div class="notice warn">Con WM: +14.649,2 € frente al actual, un +60,0 %. Las cifras publicadas incluyen valoración de carbono y retornos; no son únicamente pagos operativos.</div><p class="small muted">Informe, pp. 99–101. El porcentaje sobre PEM requiere conocer el presupuesto de obra y conciliar el cálculo.</p></section><section class="panel pad"><h2>Dimensionamiento del servicio</h2><p class="small muted">Calculadora independiente del informe. Hipótesis editables para discutir el servicio; no constituye presupuesto.</p><form id="economics-form" class="economics"><label>Coste mensual completo del WM (€)</label><input id="wm-cost" type="number" value="3500" min="0" step="100"><label>Obras atendidas simultáneamente</label><input id="wm-sites" type="range" value="2" min="1" max="6"><div class="between"><span id="sites-label">2 obras</span><output id="wm-result">1.750 €/obra·mes</output></div><label>Desplazamiento + plataforma por obra (€/mes)</label><input id="wm-extra" type="number" value="300" min="0" step="50"><p class="small muted spaced" id="wm-total">Coste base de servicio: 2.050 €/obra·mes.</p></form><p class="small muted spaced">Añadir horas de operarios, recipientes, transporte, tratamiento y rechazos. El reparto de WM no sustituye el trabajo presencial.</p></section></div><section class="panel"><div class="panelhead"><h2>Los 13 flujos del piloto</h2><span class="badge">Masa publicada · 5.955 kg</span></div><div class="tablewrap"><table><thead><tr><th>LER normalizado</th><th>Flujo</th><th class="num">kg</th><th class="num">% masa</th><th class="num">CO₂e WM · kg</th></tr></thead><tbody>${PILOT.map(p=>`<tr><td>${cb(p[0])}</td><td>${p[1]}</td><td class="num">${num(p[2])}</td><td class="num">${num(p[2]/5955*100,1)} %</td><td class="num">${num(p[5],1)}</td></tr>`).join('')}</tbody></table></div><div class="panelfoot">Emisiones por fila redondeadas de p. 87. Los totales gráficos conservan el total publicado. No sumar resultados de energía a reciclado material.</div></section>`}
function modelView(){return `<section class="panel pad"><div class="eyebrow">EL PRODUCTO QUE PROPONGO</div><h2>CUEVA Waste Manager: una capa de operación circular</h2><p class="muted">El servicio une planificación de residuos, trabajo en obra, destinos industriales y evidencia de lo que realmente sucede. El WM usa CUEVA para decidir qué hacer, quién debe hacerlo y qué falta para cerrar cada lote.</p><div class="grid3 spaced">${[['01','Preparar','Inventario y excedentes, previsión por fase, estudio/plan, acopios, destinos y formación.'],['02','Operar','Identificar lote y recipiente, registrar kg y fotos, controlar calidad, tareas y retirada.'],['03','Acreditar','Conciliar pesajes, recepción, rechazo, tratamiento y, cuando proceda, nuevo producto.']].map(v=>`<div><span class="badge blue">${v[0]}</span><h3 class="spaced">${v[1]}</h3><p class="small muted">${v[2]}</p></div>`).join('')}</div><div class="material-path"><span>Material / DPP</span> → <span>Lote de residuo</span> → <span>Tratamiento</span> → <span>Nuevo activo / DPP</span></div></section><div class="grid-even spaced"><section class="panel pad"><h2>Primer piloto CUEVA propuesto</h2><ul class="plain-list"><li>Una obra de Calaf y WM aportado o coordinado por CGM.</li><li>Prioridad: yeso y plásticos; el catálogo mantiene el resto de flujos.</li><li>Identificación de todas las unidades del alcance acordado.</li><li>QR como entrada sencilla y compatibilidad con RFID/NFC.</li><li>Destinos aceptados antes de generar grandes acopios.</li><li>Revisión con Inèdit de factores, límites y calidad de datos.</li></ul><span class="badge">Propuesta · pendiente de acuerdo de las partes</span></section><section class="panel pad"><h2>Cómo se debe cobrar y medir</h2><p class="small muted">Servicio WM + software por obra / mes, con puesta en marcha. Transporte y tratamiento separados. Un incentivo variable solo sobre ahorro o calidad acreditados, con línea base acordada y sin doble contabilización.</p><p class="small muted">CUEVA conserva el valor de identidad, protocolos, datos y continuidad del ciclo. CGM y otros gestores aportan operación y destinos. El modelo admite varios operadores por obra y por fracción.</p><h3 class="spaced">Criterios para pasar a operación</h3><div class="checkline">${ico('check')} Diccionario LER y criterios de aceptación aprobados.</div><div class="checkline">${ico('check')} Contratos, responsables y centros identificados.</div><div class="checkline">${ico('check')} Trazabilidad de masa y expedientes reconciliados.</div><div class="checkline">${ico('check')} Conexiones probadas con datos y equipos reales.</div></section></div><section class="panel pad"><h2>Alcance de esta primera versión</h2><div class="readiness"><div><b>Funciona en local</b>Catálogo, filtros, fichas, registros, tareas, solicitudes demo, fotos, formación, objetivos y exportaciones.</div><div><b>Representado en interfaz</b>Gestores, cámaras, IA, Trello, RFID y plataformas administrativas; sin comunicación real.</div><div><b>Para producción</b>Servidor, permisos, firma/evidencias, almacenamiento seguro, conectores, modelo IA y validación de campo.</div></div></section>`}
function fold(s){return String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s/g,'')}
function modal(title,html){stopScan();$('#modal-title').textContent=title;$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function closeModal(){stopScan();$('#modal').close()}
function render(){if(!nav.some(n=>n[1]===route))route='control';$('#nav').innerHTML=nav.map(n=>(n[0]?`<div class="navgroup">${n[0]}</div>`:'')+`<a class="navlink ${route===n[1]?'active':''}" href="#${n[1]}" ${route===n[1]?'aria-current="page"':''}>${ico(n[3])}${n[2]}${n[1]==='unidades'?`<span class="count">${state.lots.length}</span>`:''}</a>`).join('');const views={control,materiales:materials,unidades:units,registros:records,planificacion:planning,gestores:managersView,vision,equipo:team,objetivos:goals,formacion:learning,normativa:legal,estudio:study};$('#main').innerHTML=views[route]();if($('#filter-family'))$('#filter-family').value=filters.family||'';if($('#filter-status'))$('#filter-status').value=filters.status||'';if($('#manager-code'))$('#manager-code').value=filters.managerCode||'';document.title=nav.find(n=>n[1]===route)[2]+' · CUEVA Waste Manager';persist()}
function unitDetail(id){const l=state.lots.find(l=>l.id===id);if(!l){toast('Este evento no está vinculado a una unidad física.');return}const m=ler(l.code);modal('Expediente · '+id,`<div class="between"><span class="row">${cb(l.code)} ${m.name}</span>${badge(l.status)}</div><div class="statrow"><div><b>${kg(l.kg)}</b><small>${esc(l.method)}</small></div><div><b>${l.fill} %</b><small>Llenado · estimación</small></div><div><b>${l.quality?l.quality+' %':'Pendiente'}</b><small>Calidad visual · demo</small></div></div><div class="detailgrid"><div class="field"><label>Recipiente / lote de contenido</label><p>${esc(l.id)} / ${esc(l.lotId||('LOT-'+l.id.replace('-','')))}</p></div><div class="field"><label>Estado jurídico</label><p>Residuo ${m.hazard?'peligroso':'no peligroso · a validar'}</p></div><div class="field"><label>Ubicación</label><p>${esc(l.zone)}</p></div><div class="field"><label>Gestor propuesto</label><p>${esc(l.manager)}</p></div><div class="field"><label>Inicio del acopio</label><p>${l.date}</p></div><div class="field"><label>Identificador legible</label><p class="mono">CUEVA:WM:${esc(l.id)}</p></div></div><div class="notice ${m.hazard?'warn':''}">${esc(l.note)}</div><p class="small muted">${m.rule}</p><div class="material-path"><span>Obra / zona</span> → <span>${esc(l.lotId||('LOT-'+l.id.replace('-','')))}</span> → <span>${l.status==='Cerrado'?'Tratamiento':'Destino pendiente'}</span></div><div class="detailgrid"><div class="field"><label>Documento de identificación</label><p>${esc(l.di||'Pendiente')}</p></div><div class="field"><label>Tratamiento final</label><p>${esc(l.operation||'Sin acreditar')} ${l.proof?'· '+esc(l.proof):''}</p></div>${l.status==='Cerrado'?`<div class="field"><label>Reciclado material acreditado</label><p>${kg(l.recycled||0)}</p></div><div class="field"><label>Otras salidas / rechazo</label><p>${kg(l.kg-(l.recycled||0))}</p></div>`:''}</div><div class="actions">${btn('Etiqueta','label:'+l.id,'','scan')}${btn('Foto','photo:'+l.id,'','camera')}${btn('Observación','observation:'+l.id,'','plus')}${!['Cerrado','Recibido'].includes(l.status)?btn('Preparar retirada','collection:'+l.id,'primary','truck'):l.status==='Recibido'?btn('Registrar tratamiento','treatment:'+l.id,'primary','check'):''}${state.collections.some(c=>c.unit===id)&&l.status!=='Recibido'&&l.status!=='Cerrado'?btn('Registrar recepción','receive:'+l.id,'dark','check'):''}</div><h3 class="spaced">Histórico vinculado</h3><div class="timeline">${state.history.filter(e=>e.unit===id).slice(0,12).map(e=>`<div class="event"><div class="meta">${new Date(e.time).toLocaleString('es-ES',{timeZone:'Europe/Madrid'})} · ${esc(e.actor)}</div><p><strong>${esc(e.type)}</strong> · ${esc(e.note)}</p></div>`).join('')||'<p class="small muted">Lote inicial de demostración. Los nuevos eventos aparecerán aquí.</p>'}</div>`)}
function newRecord(){modal('Registrar una nueva unidad',`<p class="small muted">Alta de demostración. La masa se añadirá al balance; el identificador debe ser único.</p><form id="new-form"><div class="detailgrid"><div class="field"><label for="new-id">Identificador del recipiente</label><input id="new-id" name="id" required pattern="[A-Za-z0-9-]{3,30}" maxlength="30" placeholder="SAC-014"></div><div class="field"><label for="new-date">Inicio del acopio</label><input id="new-date" name="date" type="date" required value="2026-09-11"></div><div class="field full"><label for="new-code">LER propuesto</label><select id="new-code" name="code">${LER.map(l=>`<option value="${l.code}">${code(l.code)} · ${l.name}</option>`).join('')}</select></div><div class="field"><label for="new-kg">Cantidad (kg)</label><input id="new-kg" type="number" name="kg" min="0.01" max="100000" step="0.01" required></div><div class="field"><label for="new-method">Método de cantidad</label><select id="new-method" name="method"><option>Estimación</option><option>Báscula de obra</option></select></div><div class="field"><label for="new-zone">Zona de generación / acopio</label><input id="new-zone" name="zone" required maxlength="100" placeholder="Planta 3 · núcleo A"></div><div class="field"><label for="new-fill">Llenado estimado (%)</label><input id="new-fill" name="fill" type="number" min="0" max="100" value="30" required></div><div class="field full"><label for="new-note">Origen, composición y observación</label><textarea id="new-note" name="note" required maxlength="800" placeholder="Qué material lo origina y qué comprobaciones faltan…"></textarea></div></div><p class="formerror" id="form-error"></p><div class="actions"><button type="button" data-action="close">Cancelar</button><button class="primary">Guardar unidad</button></div></form>`)}
function lerDetail(c){const l=ler(c);modal('Ficha de clasificación',`<div class="between">${cb(c)}${badge(l.hazard?'Peligroso':'Revisión por origen')}</div><h2 class="spaced">${l.name}</h2><p class="muted small">${l.example}</p><div class="notice ${l.hazard?'warn':''}">${l.rule}</div><div class="detailgrid"><div class="field"><label>Familia</label><p>${l.family}</p></div><div class="field"><label>Ruta orientativa, no autorización</label><p>${l.route}</p></div></div><h3>Antes de asignar el código</h3><ul class="plain-list"><li>Confirmar que el objeto ya es residuo y su proceso de origen.</li><li>Revisar composición, residuos adheridos, FDS y caracterización necesaria.</li><li>Comprobar entrada peligrosa / no peligrosa cuando exista alternativa.</li><li>Validar aceptación y habilitación del centro de destino.</li></ul><a class="small" href="${SOURCES.find(s=>s.id==='ler').url}" target="_blank" rel="noopener">Abrir Lista Europea de Residuos oficial ↗</a><div class="actions">${btn('Buscar gestores compatibles','find-managers:'+c,'primary','truck')}</div>`)}
function classifier(){modal('Orientador LER',`<p class="small muted">Relaciona origen y composición. El resultado es una propuesta que debe validarse, no una clasificación automática.</p><form id="classifier-form"><div class="detailgrid"><div class="field"><label>¿Qué es?</label><select name="material"><option value="yeso">Yeso / placa laminada</option><option value="plastico">Plástico</option><option value="madera">Madera</option><option value="sellante">Adhesivo / sellante</option><option value="aislante">Aislamiento</option></select></div><div class="field"><label>Origen</label><select name="origin"><option value="obra">Material de construcción descartado</option><option value="envase">Envase o embalaje descartado</option><option value="producto">Producto que puede seguir usándose</option></select></div><div class="field full"><label>¿Hay sustancias peligrosas o dudas?</label><select name="hazard"><option value="unknown">No lo sabemos / falta caracterización</option><option value="no">Evaluado: no peligroso</option><option value="yes">Sí: evidencia de peligrosidad</option></select></div></div><button class="primary">Ver propuesta</button></form><div id="classifier-result" class="spaced"></div>`)}
function scan(){modal('Leer saca o contenedor',`<div class="scanbox"><div class="row">${ico('scan')}IDENTIDAD CUEVA</div><p class="small spaced">Introduce un QR, un identificador o una lectura de un lector que actúe como teclado.</p><div class="scan-id">CUEVA:WM:SAC-002</div></div><form id="scan-form"><div class="field"><label for="scan-value">Código de unidad</label><input id="scan-value" name="value" autocomplete="off" required placeholder="SAC-002 o CUEVA:WM:SAC-002"></div><p id="scan-error" class="formerror"></p><div class="actions"><button type="button" data-action="scan-camera">Usar cámara para QR</button><button type="button" data-action="sample-scan">Lectura de ejemplo</button><button class="primary">Buscar unidad</button></div></form><video id="scan-video" playsinline style="width:100%;display:none;margin-top:15px"></video><p class="small muted spaced">Cámara QR disponible solo si el navegador admite lectura de códigos. NFC / RFID necesitan un lector y un conector; aquí no hay un dispositivo conectado.</p>`);setTimeout(()=>$('#scan-value')?.focus(),50)}
function lookup(raw,source='Identificador manual'){let id=String(raw).trim().toUpperCase();if(id.startsWith('CUEVA:WM:'))id=id.slice(9);const l=state.lots.find(l=>l.id===id);if(!l){if($('#scan-error'))$('#scan-error').textContent='Unidad no encontrada. Prueba SAC-002 o registra una nueva unidad.';else toast('Unidad no encontrada');return false}log(id,'Lectura','Identificador observado; no acredita contenido ni masa.',source);unitDetail(id);return true}
async function cameraScan(){if(!('BarcodeDetector' in window)||!navigator.mediaDevices?.getUserMedia){$('#scan-error').textContent='Este navegador no admite lectura QR integrada. Usa el identificador impreso o un lector de teclado.';return}try{scanStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});const v=$('#scan-video');v.srcObject=scanStream;v.style.display='block';await v.play();const detector=new BarcodeDetector({formats:['qr_code']});let busy=false;scanInterval=setInterval(async()=>{if(busy)return;busy=true;try{const codes=await detector.detect(v);if(codes.length)lookup(codes[0].rawValue,'QR · cámara del dispositivo');}catch{}finally{busy=false}},600)}catch(e){$('#scan-error').textContent='No se pudo abrir la cámara. Puedes continuar con el identificador impreso.'}}
function stopScan(){if(scanInterval)clearInterval(scanInterval);scanInterval=null;scanStream?.getTracks().forEach(t=>t.stop());scanStream=null}
function collection(id){const list=state.lots.filter(l=>!['Cerrado','Recibido'].includes(l.status));if(!list.length){toast('No quedan unidades en obra.');return}modal('Preparar solicitud de retirada',`<div class="notice warn">Se guardará una solicitud de demostración. No se contactará con gestores ni transportistas.</div><form id="collection-form"><div class="detailgrid"><div class="field full"><label>Unidad</label><select id="collection-unit" name="unit">${list.map(l=>`<option ${l.id===id?'selected':''}>${l.id}</option>`).join('')}</select></div><div class="field full"><label>Centro / gestor propuesto</label><select id="collection-manager" name="manager"></select></div><div class="field"><label>Fecha solicitada</label><input type="date" name="date" required value="2026-09-14" min="2026-09-11"></div><div class="field"><label>Ventana horaria</label><select name="time"><option>08:00–10:00</option><option>10:00–12:00</option><option>12:00–14:00</option><option>14:00–16:00</option></select></div><div class="field full"><label>Condiciones de acceso</label><input name="access" required placeholder="Acceso norte · vehículo y carga disponibles" maxlength="200"></div></div><div class="collection-checks"><label><input type="checkbox" name="accept" required> Para la demo: aceptación del LER y condición del residuo revisadas.</label><label><input type="checkbox" name="documents" required> Para la demo: habilitación del centro y documentación revisadas.</label><label><input type="checkbox" name="safe" required> Para la demo: incidencias resueltas y carga preparada.</label></div><p id="collection-info" class="small muted"></p><p id="form-error" class="formerror"></p><div class="actions"><button class="primary">Guardar solicitud demo</button></div></form>`);updateCollectionManagers()}
function updateCollectionManagers(){const id=$('#collection-unit').value,l=state.lots.find(l=>l.id===id),ms=managers.filter(m=>m.codes.includes(l.code));$('#collection-manager').innerHTML=ms.map(m=>`<option>${m.name}</option>`).join('')||'<option value="">Sin destino compatible</option>';$('#collection-info').textContent=ler(l.code).hazard?'Residuo peligroso: el circuito ordinario está bloqueado. Resolver con responsable técnico y procedimiento específico antes de cualquier retirada real.':l.status==='Bloqueado'?'Lote bloqueado: hace falta resolver la aceptación técnica antes de programarlo.':'Contrato + DI; evaluar notificación previa y régimen territorial. Las casillas solo simulan la revisión.'}
function receive(id){modal('Recepción en destino · '+id,`<form id="receive-form" data-id="${id}"><div class="notice">Registra el pesaje recibido y la referencia de DI. La recepción no cierra el tratamiento.</div><div class="detailgrid"><div class="field"><label>Peso aceptado en destino (kg)</label><input name="kg" type="number" min="0.01" max="100000" step="0.01" value="${state.lots.find(l=>l.id===id).kg}" required></div><div class="field"><label>Referencia DI</label><input name="di" required maxlength="100" placeholder="DI-DEMO-…"></div></div><div class="actions"><button class="primary">Registrar recepción demo</button></div></form>`)}
function treatment(id){const l=state.lots.find(l=>l.id===id);modal('Tratamiento final · '+id,`<div class="notice">Masa recibida: ${kg(l.kg)}. El cierre registra el destino final; R12 y R13 se mantienen pendientes. Evidencia introducida solo en la demo.</div><form id="treatment-form" data-id="${id}"><div class="detailgrid"><div class="field"><label>Operación final</label><select name="operation"><option>R3</option><option>R4</option><option>R5</option><option>R1</option><option>D5</option><option>R12</option><option>R13</option></select></div><div class="field"><label>Kg efectivamente reciclados</label><input name="recycled" type="number" min="0" max="${l.kg}" step="0.01" required value="${l.kg}"></div><div class="field full"><label>Referencia de justificante de tratamiento</label><input name="proof" required maxlength="120" placeholder="CERT-DEMO-…"></div><div class="field full"><label>Destino del rechazo / resto</label><input name="remainder" required maxlength="200" placeholder="Sin rechazo o detallar kg y destino"></div></div><p id="form-error" class="formerror"></p><div class="actions"><button class="primary">Registrar cierre demo</button></div></form>`)}
function observation(id){modal('Observación · '+id,`<form id="observation-form" data-id="${id}"><div class="field"><label>Tipo de evento</label><select name="type"><option>Observación</option><option>Incidencia</option><option>Corrección</option><option>Control de calidad</option></select></div><div class="field spaced"><label>Qué ha ocurrido / evidencia</label><textarea name="note" required maxlength="1000"></textarea></div><div class="actions"><button class="primary">Añadir al histórico</button></div></form>`)}
function photo(id){modal('Registro fotográfico',`<div class="notice">La imagen se guarda en el espacio privado y se vincula a una unidad. No se envía a un modelo de IA.</div><form id="photo-form"><div class="field"><label>Unidad</label><select name="unit">${state.lots.map(l=>`<option ${l.id===id?'selected':''}>${l.id}</option>`).join('')}</select></div><div class="field spaced"><label>Fotografía · máximo 3 MB</label><input name="photo" type="file" accept="image/jpeg,image/png,image/webp" required></div><div class="field spaced"><label>Observación</label><textarea name="note" required maxlength="800" placeholder="Describe la composición visible y lo que queda por comprobar"></textarea></div><p id="form-error" class="formerror"></p><div class="actions"><button class="primary">Guardar evidencia</button></div></form>`)}
function newTask(){modal('Nueva tarea de obra',`<form id="task-form"><div class="field"><label>Acción concreta</label><input name="title" required maxlength="120" placeholder="Revisar…"></div><div class="detailgrid"><div class="field"><label>Responsable</label><select name="owner"><option>Waste manager</option><option>Encargado</option><option>Operario</option><option>Gestor</option></select></div><div class="field"><label>Fecha límite</label><input type="date" name="due" value="2026-09-14" required></div><div class="field"><label>Unidad</label><select name="unit"><option>Equipo</option>${state.lots.map(l=>`<option>${l.id}</option>`).join('')}</select></div><div class="field"><label>Prioridad</label><select name="priority"><option>Media</option><option>Alta</option><option>Baja</option></select></div></div><div class="actions"><button class="primary">Crear tarea</button></div></form>`)}
function moveTask(id,stage){if(!['Por hacer','En curso','Bloqueado','Hecho'].includes(stage))throw Error('Estado inválido');const t=state.tasks.find(t=>t.id===id);if(!t)throw Error('Tarea no encontrada');if(t.stage===stage)return;const old=t.stage;t.stage=stage;log(t.unit,'Tarea',`${t.title}: ${old} → ${stage}.`);render();toast('Tarea actualizada en el tablero local.');return {id,stage}}
function lesson(id){const l=lessons.find(l=>l.id===id);modal(l.title,`<span class="badge">${l.mins} min · formación de base</span><p class="spaced" style="line-height:1.8">${l.body}</p><div class="notice"><strong>${l.question}</strong></div><form id="lesson-form" data-id="${id}">${l.answers.map((a,i)=>`<label class="checkline"><input type="radio" name="answer" value="${i}" required> ${a}</label>`).join('')}<p id="lesson-result" class="small"></p><div class="actions"><button class="primary">Comprobar y completar</button></div></form>`)}
function sources(){modal('Fuentes y trazabilidad del análisis',SOURCES.map(s=>`<div class="source">${s.url?`<a href="${s.url}" target="_blank" rel="noopener">${s.name} ↗</a>`:`<b>${s.name}</b>`}<small>${s.note}</small></div>`).join(''))}
function download(name,text,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}
function csv(rows){return '\uFEFF'+rows.map(r=>r.map(v=>{let s=String(v??'');if(/^[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}).join(';')).join('\r\n')}
function exportCSV(kind){if(kind==='ler')download('CUEVA_Catalogo_LER.csv',csv([['LER','Nombre operativo','Familia','Peligroso','Regla','Ruta orientativa'],...LER.map(l=>[code(l.code),l.name,l.family,l.hazard?'Sí':'No',l.rule,l.route])]),'text/csv;charset=utf-8');else download('CUEVA_Historico_DEMO.csv',csv([['ID evento','Momento ISO','Unidad','Tipo','Autor','Método','Descripción'],...state.history.map(e=>[e.id,e.time,e.unit,e.type,e.actor,e.source,e.note])]),'text/csv;charset=utf-8')}
function unitLabel(id){const l=state.lots.find(l=>l.id===id);const qr=(typeof QR_SEED!=='undefined')?QR_SEED[id]:null;modal('Etiqueta de unidad · '+id,`<div class="between"><div><div class="eyebrow">CUEVA / WASTE MANAGER</div><h2>${id}</h2><p>${ler(l.code).name}</p>${cb(l.code)}<p class="small muted spaced">Inicio: ${l.date}<br>Zona: ${esc(l.zone)}</p></div>${qr?`<div class="qr"><img alt="QR CUEVA:WM:${id}" src="${qr}"></div>`:'<span class="badge">Identificador manual</span>'}</div><div class="notice spaced">El QR identifica el recipiente permanente; el LER impreso describe este contenido y debe actualizarse en cada ciclo. ${ler(l.code).hazard?'Es auxiliar: no sustituye el etiquetado legal completo de residuos peligrosos.':'Confirmar que el contenido coincide antes de registrar un movimiento.'} ${qr?'':'La generación QR para nuevas altas queda para la integración del servicio de etiquetado.'}</div><div class="actions">${btn('Descargar etiqueta HTML','download-label:'+id,'primary','download')}</div>`)}
function downloadLabel(id){const l=state.lots.find(l=>l.id===id),qr=typeof QR_SEED!=='undefined'?QR_SEED[id]:null;download('CUEVA_Etiqueta_'+id+'.html',`<!doctype html><html lang="es"><meta charset="utf-8"><title>${id} · CUEVA</title><style>body{font:20px Arial;color:#172a3c;max-width:600px;margin:40px auto;padding:30px;border:2px solid #172a3c}img{width:150px;float:right}h1{font-size:38px}small{font-size:14px}button{margin-top:30px;padding:10px}@media print{button{display:none}}</style><body>${qr?`<img src="${qr}" alt="QR de unidad">`:''}<small>CUEVA · ETIQUETA DE DEMOSTRACIÓN</small><h1>${id}</h1><p>${ler(l.code).name}</p><b>LER ${code(l.code)}</b><p>Inicio acopio: ${l.date}<br>${esc(l.zone)}</p><p>Identificador: CUEVA:WM:${id}</p><small>Etiqueta auxiliar. No sustituye el etiquetado reglamentario de residuos peligrosos. El contenido debe verificarse.</small><br><button onclick="window.print()">Imprimir etiqueta</button></body></html>`,'text/html')}
function connectors(kind='all'){modal(kind==='trello'?'Trello · diseño de conexión':'Conexiones del centro de operaciones',`<div class="notice">Estas conexiones están diseñadas en el prototipo, pero no hay cuentas, equipos ni servicios externos conectados.</div>${[['Trello','Tablero local ↔ listas, tarjetas, responsables y fechas. Vincular cada tarjeta con obra y lote. Sincronización futura con autorización de la cuenta.'],['Gestores / ERP','Solicitud → aceptación → pesaje → rechazo → tratamiento. API o intercambio de ficheros según operador; validación del centro y LER.'],['eSIR / SDR','Adaptador documental según ámbito territorial. Generar un CSV no equivale a tramitar un DI o una notificación.'],['RFID / NFC / QR','Eventos de lectura con dispositivo, fecha, zona y calidad. Resolver duplicados, lecturas cruzadas y cambios de recipiente sin perder el lote.'],['Cámaras / visión','Pasarela de vídeo, máscaras de privacidad y cola de inferencia. Modelo versionado, umbral calibrado y revisión humana.'],['Operación sin cobertura','Cola local cifrada y sincronización idempotente por implementar. El prototipo conserva estado solo en el navegador.']].filter(v=>kind!=='trello'||v[0]==='Trello').map(v=>`<div class="source"><div class="between"><b>${v[0]}</b><span class="badge amber">Sin conectar</span></div><p class="small muted spaced">${v[1]}</p></div>`).join('')}`)}
function about(){modal('CUEVA Waste Manager · primer prototipo',`<p>Un centro de operaciones para coordinar materiales, residuos y destinos desde la obra.</p><div class="notice">Entorno de demostración. Guarda cambios en este navegador. No se envían solicitudes, mensajes o datos a terceros; no ejecuta segmentación IA ni certifica cumplimiento.</div><div class="actions">${btn('Descargar datos JSON','export-json','','download')}<a href="CUEVA_Waste_Manager_Prototipo.html" download>Descargar prototipo HTML ↗</a></div><p class="small muted spaced">Referencia: informe CREC 2025 aportado por Mariano / CGM. Masas iniciales basadas en el piloto; resto de la operativa simulada.</p><div class="actions">${btn('Restaurar datos de ejemplo','reset-confirm','danger')}</div>`)}
function handleAction(action){const pos=action.indexOf(':'),type=pos<0?action:action.slice(0,pos),arg=pos<0?'':action.slice(pos+1);switch(type){case'nav':closeModal();go(arg);break;case'new':newRecord();break;case'unit':unitDetail(arg);break;case'scan':scan();break;case'scan-camera':cameraScan();break;case'sample-scan':lookup('SAC-002','QR · ejemplo simulado');break;case'classifier':classifier();break;case'collection':collection(arg);break;case'receive':receive(arg);break;case'treatment':treatment(arg);break;case'photo':photo(arg);break;case'observation':observation(arg);break;case'label':unitLabel(arg);break;case'download-label':downloadLabel(arg);break;case'newtask':newTask();break;case'close':closeModal();break;case'trello':connectors('trello');break;case'connections':connectors();break;case'export-ler':exportCSV('ler');break;case'export-records':exportCSV('records');break;case'export-json':download('CUEVA_Waste_Manager_DEMO.json',JSON.stringify({schema:'cueva-wm-demo-v1',exportedAt:new Date().toISOString(),warning:'Datos locales de demostración',...state},null,2),'application/json');break;case'sources':sources();break;case'find-managers':closeModal();route='gestores';location.hash='gestores';filters={managerCode:arg};render();break;case'lesson':lesson(arg);break;case'message':go('equipo');setTimeout(()=>$('#message-form textarea')?.focus(),30);break;case'manager':{const m=managers.find(m=>m.name===arg);modal(m.name,`<span class="badge amber">Ficha de diseño · habilitación sin verificar</span><p class="spaced">${m.note}</p><div class="taglist">${m.codes.map(cb).join('')}</div><div class="detailgrid"><div class="field"><label>NIMA del centro</label><p>Pendiente</p></div><div class="field"><label>Autorización y vigencia</label><p>Pendiente</p></div><div class="field"><label>Operaciones propuestas</label><p>${m.operation}</p></div><div class="field"><label>Criterios de recepción</label><p>Calidad, humedad, impropios, lote mínimo y rechazo por acordar.</p></div></div><p class="small muted">Una empresa puede operar varios centros con distintos LER y operaciones. La autorización debe verificarse por instalación.</p>`);break}case'visual-review':modal('Registrar una revisión visual',`<div class="notice">La fotografía de referencia demuestra la interfaz. La observación se guardará como ejemplo, sin asignar automáticamente LER, peso ni peligrosidad.</div><form id="visual-form"><div class="field"><label>Conclusión de revisión</label><select name="result"><option>Solicitar segregación de impropios</option><option>Pedir una imagen más nítida</option><option>Solicitar identificación técnica</option></select></div><div class="field spaced"><label>Comentario del WM</label><textarea name="note" required maxlength="600"></textarea></div><div class="actions"><button class="primary">Guardar revisión demo</button></div></form>`);break;case'target':modal('Meta interna de reciclado',`<form id="target-form"><div class="field"><label>Objetivo (%)</label><input name="target" type="number" min="1" max="100" required value="${state.target}"></div><p class="small muted spaced">Esta meta es operativa. No modifica los umbrales normativos ni declara cumplimiento legal.</p><div class="actions"><button class="primary">Guardar meta</button></div></form>`);break;case'redeem':if(state.points<100){toast('Necesitas 100 puntos para este reconocimiento.');return}state.points-=100;state.redemptions.push({date:new Date().toISOString(),name:'Reconocimiento del equipo',points:100});log('Equipo','Reconocimiento','Canje simbólico de 100 puntos; sin premio externo.');render();toast('Reconocimiento de equipo canjeado en la demo.');break;case'edit-task':{const t=state.tasks.find(t=>t.id===arg);modal(t.id+' · '+t.title,`<p class="small muted">Responsable: ${esc(t.owner)} · Unidad: ${esc(t.unit)} · Fecha: ${t.due}</p><label class="field"><span class="small muted">Estado</span><select data-task-stage="${t.id}">${['Por hacer','En curso','Bloqueado','Hecho'].map(s=>`<option ${s===t.stage?'selected':''}>${s}</option>`).join('')}</select></label>`);break}case'passport':modal('Pasaporte de material · '+arg,`<span class="badge blue">Ejemplo conceptual · producto en uso</span><div class="material-path"><span>Fabricación</span> → <span>Uso</span> → <span>Inspección</span> → <span>Siguiente ciclo</span></div><p>El pasaporte vincula identidad del producto, composición, documentación técnica, origen reciclado cuando se acredite, ubicación y eventos.</p><p class="small muted">Cuando corresponde: POI, mantenimiento, reparación, retorno y posterior transformación. La declaración de residuo exige una decisión diferenciada; no se asigna LER a un producto solo por ser usado.</p>`);break;case'reset-confirm':modal('Restaurar datos de demostración',`<p>Se borrarán los registros, fotografías, tareas y cambios que hayas añadido en este navegador. Puedes exportarlos antes.</p><div class="actions">${btn('Exportar primero','export-json')}${btn('Cancelar','close')}${btn('Restaurar demo','reset','danger')}</div>`);break;case'reset':state=structuredClone(seed);closeModal();render();toast('Datos de demostración restaurados.');break;default:toast('Acción no disponible.')}}
document.addEventListener('click',e=>{const tab=e.target.closest('[data-tab]');if(tab){const [k,v]=tab.dataset.tab.split(':');if(k==='material')materialTab=v;if(k==='plan')planTab=v;if(k==='analysis')analysisTab=v;filters={};render();return}const a=e.target.closest('[data-action]');if(a){handleAction(a.dataset.action);return}const u=e.target.closest('[data-unit]');if(u){unitDetail(u.dataset.unit);return}const l=e.target.closest('[data-ler]');if(l)lerDetail(l.dataset.ler)});
document.addEventListener('keydown',e=>{const u=e.target.closest?.('[data-unit][role=button]');if(u&&(e.key==='Enter'||e.key===' ')){e.preventDefault();unitDetail(u.dataset.unit)}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchModal()}if(e.key==='Escape'){$('#sidebar').classList.remove('open');stopScan()}});
document.addEventListener('input',e=>{if(e.target.id==='filter-q'){const start=e.target.selectionStart;filters.q=e.target.value;render();$('#filter-q').focus();$('#filter-q').setSelectionRange(start,start)}if(['wm-cost','wm-sites','wm-extra'].includes(e.target.id)){const c=Math.max(0,Number($('#wm-cost').value)||0),n=Math.max(1,Number($('#wm-sites').value)||1),x=Math.max(0,Number($('#wm-extra').value)||0);$('#sites-label').textContent=n+' obra'+(n>1?'s':'');$('#wm-result').textContent=num(c/n)+' €/obra·mes';$('#wm-total').textContent='Coste base de servicio: '+num(c/n+x)+' €/obra·mes.'}if(e.target.id==='global-search')searchResults(e.target.value)});
document.addEventListener('change',e=>{if(e.target.id==='filter-family'){filters.family=e.target.value;render()}if(e.target.id==='filter-status'){filters.status=e.target.value;render()}if(e.target.id==='manager-code'){filters.managerCode=e.target.value;render()}if(e.target.id==='collection-unit')updateCollectionManagers();if(e.target.id==='mask-toggle'){maskOn=e.target.checked;render()}if(e.target.dataset.taskStage)moveTask(e.target.dataset.taskStage,e.target.value)});
document.addEventListener('dragstart',e=>{const t=e.target.closest('[data-task]');if(t)e.dataTransfer.setData('text/plain',t.dataset.task)});
document.addEventListener('dragover',e=>{if(e.target.closest('[data-drop]'))e.preventDefault()});document.addEventListener('drop',e=>{const c=e.target.closest('[data-drop]');if(c){e.preventDefault();const id=e.dataTransfer.getData('text/plain');if(state.tasks.some(t=>t.id===id))moveTask(id,c.dataset.drop)}});
document.addEventListener('submit',async e=>{const f=e.target;if(!f.id)return;e.preventDefault();const d=Object.fromEntries(new FormData(f));const err=t=>{const el=$('#form-error');if(el)el.textContent=t;else toast(t)};try{switch(f.id){case'new-form':{const id=d.id.trim().toUpperCase();if(!/^[A-Z0-9-]{3,30}$/.test(id))return err('Identificador inválido. Usa letras, números y guiones.');if(state.lots.some(l=>l.id===id))return err('Este identificador ya existe. Abre su expediente para añadir eventos.');if(!LER.some(l=>l.code===d.code)||!Number.isFinite(+d.kg)||+d.kg<=0||+d.kg>100000)return err('Comprueba LER y cantidad positiva.');if(!d.zone.trim()||!d.note.trim())return err('Indica origen y observación.');state.lots.push({id,code:d.code,kg:+d.kg,fill:Math.max(0,Math.min(100,+d.fill)),zone:d.zone.trim(),date:d.date,method:d.method,note:d.note.trim(),status:ler(d.code).hazard?'Cuarentena':'Revisión',quality:0,manager:'Sin asignar'});log(id,'Alta',`${kg(+d.kg)} · ${ler(d.code).name}. LER propuesto pendiente de validación.`,d.method);closeModal();go('unidades');render();toast('Unidad registrada. Su clasificación queda pendiente de revisión.');break}case'scan-form':lookup(d.value);break;case'classifier-form':{const out=$('#classifier-result');let c;if(d.origin==='producto'){out.innerHTML='<div class="notice success">Mantener como producto / material. Revisar reutilización, retorno o mantenimiento antes de declarar residuo. No asignar LER automáticamente.</div>';return}if(d.hazard==='unknown'){out.innerHTML='<div class="notice warn">Clasificación pendiente. Identificar composición y peligrosidad con el responsable técnico; no cerrar un LER por intuición o por imagen.</div>';return}if(d.origin==='envase'){if(!['plastico','madera'].includes(d.material)){out.innerHTML='<div class="notice warn">La combinación seleccionada no identifica suficientemente el envase. Revisa su material y contenido residual.</div>';return}c=d.hazard==='yes'?'150110*':d.material==='plastico'?'150102':'150103'}else{c=({yeso:['170802','170801*'],plastico:['170203','170204*'],madera:['170201','170204*'],sellante:['080410','080409*'],aislante:['170604','170603*']}[d.material])[d.hazard==='yes'?1:0]}out.innerHTML=`<div class="notice"><b>Propuesta: ${code(c)} · ${ler(c).name}</b><p class="small spaced">${ler(c).rule}</p><button type="button" data-ler="${c}">Abrir ficha</button></div>`;break}case'collection-form':{const l=state.lots.find(l=>l.id===d.unit),m=managers.find(m=>m.name===d.manager);if(!m||!m.codes.includes(l.code))return err('No existe un destino compatible para este LER.');if(ler(l.code).hazard||['Bloqueado','Cuarentena'].includes(l.status))return err('Circuito bloqueado. Este prototipo no autoriza retiradas de peligrosos ni lotes sin destino aceptado.');if(state.collections.some(c=>c.unit===l.id&&c.status==='Solicitada'))return err('Esta unidad ya tiene una solicitud pendiente.');if(!d.accept||!d.documents||!d.safe)return err('Completa las comprobaciones de la demo.');const c={id:'RET-'+String(state.collections.length+1).padStart(3,'0'),unit:l.id,manager:m.name,date:d.date,time:d.time,access:d.access,status:'Solicitada'};state.collections.push(c);l.manager=m.name;l.status='Listo';log(l.id,'Solicitud',`${c.id} · ${m.name} · ${d.date} ${d.time}. Registrada en el espacio privado; sin envío a terceros.`);closeModal();go('gestores');render();toast('Solicitud preparada en la demo. No se ha enviado al gestor.');break}case'receive-form':{const l=state.lots.find(l=>l.id===f.dataset.id);if(ler(l.code).hazard||!state.collections.some(c=>c.unit===l.id))return err('No hay una solicitud ordinaria preparada.');if(!Number.isFinite(+d.kg)||+d.kg<=0||+d.kg>100000)return err('Peso inválido.');const old=l.kg;l.kg=+d.kg;l.di=d.di.trim();l.method='Pesaje destino';l.status='Recibido';l.process='Recibido';l.fill=0;l.zone='Destino · recibido';state.collections.filter(c=>c.unit===l.id).forEach(c=>c.status='Recibido');log(l.id,'Recepción',`${kg(l.kg)} aceptados. Diferencia frente a origen: ${num(l.kg-old,2)} kg. ${l.di}.`,'Pesaje destino · demo');unitDetail(l.id);render();toast('Recepción registrada; tratamiento final pendiente.');break}case'treatment-form':{const l=state.lots.find(l=>l.id===f.dataset.id),r=+d.recycled;if(l.status!=='Recibido'||!l.di)return err('Hace falta registrar recepción y documento de identificación.');if(['R12','R13'].includes(d.operation))return err('R12 y R13 son operaciones intermedias. El tratamiento final sigue pendiente.');if(!['R3','R4','R5','R1','D5'].includes(d.operation))return err('Operación no válida.');if(!Number.isFinite(r)||r<0||r>l.kg)return err('La masa reciclada debe estar entre 0 y la masa recibida.');if(['R1','D5'].includes(d.operation)&&r!==0)return err('Energía o eliminación no son reciclado material: indica 0 kg reciclados.');if(!d.proof.trim()||!d.remainder.trim())return err('Añade referencia documental y destino del resto.');l.operation=d.operation;l.proof=d.proof.trim();l.recycled=r;l.status='Cerrado';l.process='Tratado';l.note=`Tratamiento ${d.operation}. Resto: ${d.remainder}`;log(l.id,'Tratamiento',`${d.operation} · ${kg(r)} reciclados; ${kg(l.kg-r)} en otras salidas. Referencia: ${l.proof}. Demo.`);unitDetail(l.id);render();toast('Cierre de demostración registrado con balance de masa.');break}case'observation-form':{if(!d.note.trim())return err('Escribe la observación.');log(f.dataset.id,d.type,d.note.trim());unitDetail(f.dataset.id);render();toast('Evento añadido al histórico.');break}case'photo-form':{const file=f.elements.photo.files[0];if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type))return err('Selecciona una imagen JPEG, PNG o WebP.');if(file.size>3*1024*1024)return err('La imagen supera 3 MB. Selecciona una versión menor.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});state.photos.push({id:'IMG-'+Date.now(),unit:d.unit,note:d.note.trim(),data,date:new Date().toISOString()});log(d.unit,'Foto',d.note.trim(),'Imagen aportada · sin IA');closeModal();go('vision');render();toast(memoryOnly?'Imagen en memoria. Exporta los datos antes de cerrar.':'Imagen guardada y vinculada a la unidad.');break}case'task-form':{if(!d.title.trim())return err('Escribe una acción concreta.');const t={...d,title:d.title.trim(),id:'T-'+Date.now().toString().slice(-7),stage:'Por hacer'};state.tasks.push(t);log(d.unit,'Tarea','Nueva tarea: '+t.title+' · '+t.owner);closeModal();go('planificacion');render();toast('Tarea creada.');break}case'time-form':{const mins=+d.minutes;if(!Number.isInteger(mins)||mins<1||mins>1440)return err('Indica entre 1 y 1.440 minutos.');state.minutes.unshift({activity:d.activity,minutes:mins,date:new Date().toISOString()});log('Equipo','Tiempo',d.activity+' · '+mins+' min.');render();toast('Tiempo registrado.');break}case'message-form':{if(!d.message.trim())return;state.messages.push({role:d.role,text:d.message.trim(),unit:d.unit,time:new Date().toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'})+' · local'});log(d.unit,'Aviso',d.message.trim(),'Mensaje registrado',d.role+' · demo');render();toast('Aviso guardado localmente; no enviado a personas reales.');break}case'lesson-form':{const l=lessons.find(l=>l.id===f.dataset.id);if(+d.answer!==l.correct){$('#lesson-result').textContent='Revisa el criterio del módulo y vuelve a intentarlo.';return}const fresh=!state.learning.includes(l.id);if(fresh){state.learning.push(l.id);state.points+=20;log('Equipo','Formación',l.title+' · caso completado en demo.')}$('#lesson-result').textContent=fresh?'Correcto. Módulo completado y 20 puntos añadidos.':'Correcto. Este módulo ya estaba completado; no se duplican puntos.';render();break}case'visual-form':state.tasks.push({id:'T-'+Date.now().toString().slice(-7),title:d.result,unit:'Imagen de referencia',owner:'Waste manager',due:'2026-09-14',stage:'Por hacer',priority:'Media'});log('Imagen de referencia','Revisión visual',d.result+': '+d.note,'Demostración manual · sin IA');closeModal();render();toast('Revisión guardada y tarea creada en el tablero.');break;case'target-form':if(!Number.isFinite(+d.target)||+d.target<1||+d.target>100)return err('Objetivo entre 1 y 100 %.');state.target=+d.target;log('Equipo','Objetivo','Meta interna ajustada a '+d.target+' %.');closeModal();render();toast('Meta interna actualizada.');break}}catch(error){err('No se ha podido completar la acción. Revisa los campos y vuelve a intentarlo.');console.error(error)}});
function searchModal(){modal('Buscar en CUEVA',`<input id="global-search" style="width:100%" aria-label="Buscar en toda la aplicación" placeholder="Unidad, material, LER o sección…"><div id="global-results" class="results spaced"></div>`);searchResults('');setTimeout(()=>$('#global-search')?.focus(),30)}
function searchResults(q){const query=fold(q),ls=state.lots.filter(l=>!q||fold(l.id+' '+ler(l.code).name+' '+l.code).includes(query)).slice(0,6),cs=q?LER.filter(l=>fold(l.name+' '+l.code).includes(query)).slice(0,5):[];$('#global-results').innerHTML=ls.map(l=>`<button data-unit="${l.id}"><span>${l.id} · ${ler(l.code).name}</span>${cb(l.code)}</button>`).join('')+cs.map(l=>`<button data-ler="${l.code}"><span>${l.name}</span>${cb(l.code)}</button>`).join('')+nav.filter(n=>q&&fold(n[2]).includes(query)).map(n=>`<button data-action="nav:${n[1]}">${n[2]} ${ico('arrow')}</button>`).join('');if(!$('#global-results').innerHTML)$('#global-results').innerHTML='<p class="empty">No hay resultados.</p>'}
$('#close-modal').onclick=closeModal;$('#modal').addEventListener('close',stopScan);$('#menu').onclick=()=>$('#sidebar').classList.toggle('open');$('#about').onclick=about;$('#search-open').onclick=searchModal;$('#notifications').onclick=()=>{go('unidades');filters={status:'Revisión'};render()};$('#bell-icon').innerHTML=ico('bell');window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'control';if(next!==route)filters={};route=next;render();window.scrollTo(0,0)});
render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});for(const tool of [{name:'read_waste_manager_summary',title:'Leer resumen de residuos',description:'Consulta métricas locales del prototipo CUEVA y unidades. Datos de demostración.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('Sin parámetros');const t=totals();return{demo:true,totalKg:t.total,eligibleKg:t.base,recycledKg:t.recycled,units:state.lots.map(l=>({id:l.id,ler:l.code,status:l.status}))}}},{name:'update_local_task_stage',title:'Mover tarea local',description:'Cambia el estado de una tarea de demostración, guarda el cambio local y añade un evento al histórico. No sincroniza con Trello.',inputSchema:{type:'object',properties:{taskId:{type:'string'},stage:{type:'string',enum:['Por hacer','En curso','Bloqueado','Hecho']}},required:['taskId','stage'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['taskId','stage'].includes(k))||typeof input.taskId!=='string'||typeof input.stage!=='string')throw Error('Entrada inválida');return moveTask(input.taskId,input.stage)||{id:input.taskId,stage:input.stage}}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}
